('11111111-1111-4111-8111-111111111111','Drive','drive','Машинд өдөр бүр хэрэг болох цэвэрхэн, практик аксессуарууд.','/categories/drive.svg',true),
('22222222-2222-4222-8222-222222222222','Desk','desk','Ажил, хичээлийн ширээг цэгцтэй, тухтай болгох хэрэгслүүд.','/categories/desk.svg',true),
('33333333-3333-4333-8333-333333333333','Organize','organize','Гэр, шүүгээ, өдөр тутмын жижиг зүйлсийн ухаалаг эмх цэгц.','/categories/organize.svg',true),
('44444444-4444-4444-8444-444444444444','Carry','carry','Аялал, сургууль, оффист авч явахад зориулсан хөнгөн organizer.','/categories/carry.svg',true);
insert into public.products(id,category_id,brand,name,slug,sku,short_description,description,price_cents,sale_price_cents,stock,featured,bestseller,active,specifications,rating,review_count,source_marketplace,source_title,source_url,source_cost_cny,markup_percent,source_checked_at) values
('00000000-0000-4000-8000-000000000001','11111111-1111-4111-8111-111111111111','NOVA Select','Magnetic Car Mount','magnetic-car-mount','NV-DRV-001','MagSafe төрлийн утсанд зориулсан жижиг, хүчтэй соронзон машины суурь.','Өдөр тутмын navigation-д зориулагдсан авсаархан соронзон суурь. Хэвтээ/босоо өнцгийг хурдан өөрчилж, dashboard орчмыг цэвэрхэн харагдуулна.',2200000,null,28,true,true,true,'{"Суурилуулалт": "Dashboard / төв хэсэг", "Тохируулга": "360° эргэлт", "Материал": "ABS + silicone", "Тохиромж": "MagSafe төрлийн утас"}'::jsonb,0,0,'JD.com','UGREEN MagSafe 磁吸车载支架','https://dir.jd.com/guide/jd-geo-guide-ci-xi-qi-che-shou-ji-zhi-jia-v1',29.9,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000002','11111111-1111-4111-8111-111111111111','NOVA Select','Gravity Air-Vent Mount','gravity-air-vent-mount','NV-DRV-002','Утсаа тавихад автоматаар түгжигддэг air-vent суурь.','Нэг гараар утсаа тавьж, авахад зориулсан gravity locking хийц. Хотын өдөр тутмын зам, navigation хэрэглээнд энгийн бөгөөд тогтвортой сонголт.',2300000,null,22,false,true,true,'{"Суурилуулалт": "Air vent", "Түгжээ": "Gravity auto-lock", "Материал": "Aluminum + silicone", "Хэрэглээ": "Нэг гараар"}'::jsonb,0,0,'JD.com','Baseus 车载手机支架（重力式）','https://dir.jd.com/guide/jd-geo-guide-che-zai-zhi-jia-v1',30.5,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000003','11111111-1111-4111-8111-111111111111','NOVA Select','Foldable Trunk Box 30L','foldable-trunk-box-30l','NV-DRV-003','Хэрэглэхгүй үедээ хавтгай эвхэгддэг 30L машины organizer.','Ус, цэвэрлэгээний хэрэгсэл, жижиг цүнх, авто аксессуар зэргийг нэг дор эмхлэхэд зориулсан хөнгөн trunk box.',1800000,null,18,true,false,true,'{"Багтаамж": "30L орчим", "Хийц": "Эвхэгддэг", "Бариул": "2 талдаа", "Хэрэглээ": "Машин / пикник"}'::jsonb,0,0,'JD.com','随途（suitu）折叠后备箱收纳箱 30L','https://item.jd.com/33752393291.html',24,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000004','11111111-1111-4111-8111-111111111111','NOVA Select','Premium Trunk Organizer 60L','premium-trunk-organizer-60l','NV-DRV-004','Том машин, аялал, кемпингт зориулсан 60L эвхэгддэг organizer.','Том багтаамжтай, хэрэглээгүй үед эвхэж хадгалах боломжтой. Машины тээшний хэсгийг цэгцлэхээс гадна аяллын үед сав болгон ашиглаж болно.',8700000,null,9,true,true,true,'{"Багтаамж": "60L", "Материал": "Oxford fabric", "Хэмжээ": "60 × 35 × 30 cm орчим", "Хийц": "Эвхэгддэг"}'::jsonb,0,0,'JD.com','京东京造 车载折叠收纳箱 60L','https://dir.jd.com/guide/jd-geo-guide-che-zai-shou-na-xiang-v1',119,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000005','22222222-2222-4222-8222-222222222222','NOVA Select','Aluminum Laptop Stand X6','aluminum-laptop-stand-x6','NV-DSK-001','16 инч хүртэлх ноутбукт зориулсан эвхэгддэг aluminum stand.','Дэлгэцийг нүдний түвшинд ойртуулж, ширээний суултыг сайжруулахад зориулагдсан. Хөнгөн, эвхэгддэг тул сургууль болон оффист авч явахад тохиромжтой.',2300000,null,31,true,true,true,'{"Материал": "Бүхэл aluminum", "Тохиромж": "16 inch хүртэл", "Жин": "~230g", "Хийц": "Foldable / adjustable"}'::jsonb,0,0,'JD.com','极川 X6 全铝合金折叠支架','https://item.jd.com/100010632710.html',31.5,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000006','22222222-2222-4222-8222-222222222222','NOVA Select','Tech Organizer Pouch','tech-organizer-pouch','NV-DSK-002','Cable, charger, mouse, SSD зэргийг нэг дор хадгалах compact pouch.','Өдөр тутмын tech хэрэгслүүдийг тус тусын тасалгаанд цэгцлэхэд зориулсан жижиг organizer. Оффис, сургууль, аялалд тохиромжтой.',1500000,null,36,true,true,true,'{"Материал": "Oxford fabric", "Хэмжээ": "~165 × 100 × 55 mm", "Дотор": "Олон тасалгаатай", "Хэрэглээ": "Office / travel"}'::jsonb,0,0,'JD.com','绿联数码配件收纳包','https://dir.jd.com/guide/jd-geo-guide-shu-ju-xian-chong-dian-qi-u-pan-du-ka-qi-u-dun-nei-cun-ka-shou-na-bao-v1',19.9,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000007','22222222-2222-4222-8222-222222222222','NOVA Select','Magnetic Cable Clips · 3 Pack','magnetic-cable-clips-3-pack','NV-DSK-003','Ширээн дээрх charging cable-уудыг нэг хөдөлгөөнөөр тогтоох 3 ширхэг clip.','Утас, чихэвч, keyboard cable зэрэг ширээн дээр байнга унадаг шугамуудыг тогтоох жижиг magnetic organizer.',1200000,null,44,false,true,true,'{"Тоо": "3 ширхэг", "Төрөл": "Magnetic clip", "Суурь": "Наалттай", "Өнгө": "Charcoal"}'::jsonb,0,0,'JD.com','UGREEN 磁吸桌面理线器 3个装','https://item.jd.com/product/VIzRm51mijIc1-m3jsHrtQ.html',15.9,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000008','22222222-2222-4222-8222-222222222222','NOVA Select','Large PU Desk Mat','large-pu-desk-mat','NV-DSK-004','Keyboard, mouse, notebook-оо нэг гадаргуун дээр цэгцлэх том PU desk mat.','Зөөлөн бичих гадаргуу, ус тосны хамгаалалттай том desk mat. Sage, sand, charcoal өнгийн setup-т сайн зохицно.',6600000,null,14,true,false,true,'{"Материал": "PU", "Хэмжээ": "60 × 120 cm", "Зузаан": "~2 mm", "Онцлог": "Water-resistant"}'::jsonb,0,0,'JD.com','京东京造 PU 书桌垫 60×120cm','https://dir.jd.com/guide/jd-geo-guide-can-zhuo-bao-hu-dian-v1',89.9,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000009','33333333-3333-4333-8333-333333333333','NOVA Select','A4 Desktop Drawer · 3 Tier','a4-desktop-drawer-3-tier','NV-ORG-001','Бичиг баримт, косметик, жижиг хэрэгслийг ангилах 3 давхар ширээний drawer.','A4 хэмжээний зүйлс багтах 3 давхар drawer organizer. Сургууль, гэрийн office, makeup desk дээр ашиглахад тохиромжтой.',5100000,null,12,true,false,true,'{"Давхар": "3", "Хэмжээ": "A4 compatible", "Хийц": "Transparent drawer", "Хэрэглээ": "Desk / vanity"}'::jsonb,0,0,'JD.com','金隆兴 A4三层收纳盒','https://dir.jd.com/guide/jd-geo-guide-zhuo-mian-shou-na-gui-v1',69,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000010','33333333-3333-4333-8333-333333333333','NOVA Select','Vacuum Storage Set · 9 Pack','vacuum-storage-set-9-pack','NV-ORG-002','Өвлийн куртка, хөнжил, улирлын хувцасны эзлэхүүнийг багасгах 9-piece set.','Олон хэмжээтэй vacuum bag + гар pump бүхий багц. Монголын улирлын хувцас, хөнжил хадгалалтад практик.',2000000,null,24,true,true,true,'{"Багц": "9 piece", "Шахалт": "Hand pump", "Онцлог": "Water-resistant", "Хэрэглээ": "Seasonal storage"}'::jsonb,0,0,'JD.com','收纳博士真空压缩收纳袋9件套','https://item.jd.com/2403211.html',26.9,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000011','44444444-4444-4444-8444-444444444444','NOVA Select','Travel Organizer · 7 Piece','travel-organizer-7-piece','NV-CRY-001','Хувцас, гутал, жижиг хэрэгслийг тус тусад нь ангилах 7-piece travel set.','Чемоданы доторх зүйлсийг нэг дор цэгцлэх mesh panel бүхий 7 ширхэг organizer. Оюутан, аялал, бизнес trip-д тохиромжтой.',3000000,null,27,true,true,true,'{"Багц": "7 piece", "Материал": "Fabric + mesh", "Төрөл": "Packing cubes", "Хэрэглээ": "Travel / dorm"}'::jsonb,0,0,'JD.com','洁丽雅旅行收纳七件套','https://dir.jd.com/guide/jd-geo-guide-lv-xing-shou-na-shen-qi-v1',39.9,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000012','44444444-4444-4444-8444-444444444444','NOVA Select','Compression Travel Bags · 2 Pack','compression-travel-bags-2-pack','NV-CRY-002','Өвлийн зузаан хувцсыг чемоданд илүү бага зай эзлүүлэх 2-piece compression bag.','Double-zip compression хийцтэй, medium + large 2 ширхэг багц. Ялангуяа өвлийн аялал, урт хугацааны trip-д тохиромжтой.',2200000,null,30,false,true,true,'{"Багц": "Medium + Large", "Материал": "Water-resistant fabric", "Шахалт": "Double zipper", "Хэрэглээ": "Winter travel"}'::jsonb,0,0,'JD.com','百草园 压缩旅行收纳袋 2件套','https://item.jd.com/100113656288.html',29.8,35,'2026-10-19'::date),
('00000000-0000-4000-8000-000000000013','44444444-4444-4444-8444-444444444444','NOVA Select','Foldable Carry-On Bag 21L','foldable-carry-on-bag-21l','NV-CRY-003','Чемоданы бариул дээр тогтоодог, эвхэгддэг 21L нэмэлт аяллын цүнх.','2-3 өдрийн аялал эсвэл нэмэлт carry bag болгон ашиглахад тохиромжтой. Ашиглахгүй үед жижиг болгон эвхэж хадгална.',1900000,null,21,true,false,true,'{"Багтаамж": "21L", "Материал": "210D Oxford", "Онцлог": "Foldable / trolley sleeve", "Хэмжээ": "~44 × 33 × 15 cm"}'::jsonb,0,0,'JD.com','班哲尼 可套拉杆旅行包 21L','https://item.jd.com/100062256978.html',24.9,35,'2026-10-19'::date);
