-- Localize NOVA for Mongolia and seed source-tracked catalog
alter table public.products add column if not exists brand text not null default 'NOVA Select';
alter table public.products add column if not exists source_marketplace text;
alter table public.products add column if not exists source_title text;
alter table public.products add column if not exists source_url text;
alter table public.products add column if not exists source_cost_cny numeric(10,2) check (source_cost_cny is null or source_cost_cny >= 0);
alter table public.products add column if not exists markup_percent numeric(6,2) check (markup_percent is null or markup_percent >= 0);
alter table public.products add column if not exists source_checked_at date;

update public.orders set currency='mnt' where currency='usd' and status='pending';
alter table public.orders alter column currency set default 'mnt';

delete from public.product_images;
delete from public.favorites;
delete from public.cart_items;
delete from public.reviews;
delete from public.products;
delete from public.categories;



